    state increase {
        enter { k1 = 1; k2 = 0; n = 0; }
    }

    state hold {
        enter { k1 = 0; k2 = 0; n = 0; }
    }

    state decrease {
        enter { k1 = 0; k2 = 1; n = 500; }
    }

    increase -> hold : if [slp <= 0.01];
    hold -> increase : if [slp > 0.01];
    hold -> decrease : if [slp < -0.01];
    decrease -> hold : if [slp >= -0.01];
}
\"\"\"
final_dsl = \"\"\"def int k1 = 0;
def int k2 = 0;
def int n = 0;
def float slp = 0.0;

state ABSBrakeSupervisor {
    [*] -> increase;

    state increase {
        during { k1 = 1; k2 = 0; n = 0; }
    }

    state hold {
        during { k1 = 0; k2 = 0; n = 0; }
    }

    state decrease {
        during { k1 = 0; k2 = 1; n = 500; }
    }

    increase -> hold : if [slp <= 0.01];
    hold -> increase : if [slp > 0.01];
    hold -> decrease : if [slp < -0.01];
    decrease -> hold : if [slp >= -0.01];
}
\"\"\"
(out/'final_model.fcstm').write_text(final_dsl, encoding='utf-8')
ctx=StageContext(nl=context_nl, current_dsl=final_dsl)
