sem=sem_meta=build=None
if parse.ok:
    sem, sem_meta, build=run_sd3_semantic(final_dsl, ctx)
design=design_meta=None
if sem and sem.ok:
    design, design_meta=run_sd4_design(ctx, policy_profile='generated_candidate')

scenarios=[
    TestScenario(
        name='S001_default_enters_increase_outputs',
        description='default_prefix: one empty cycle dispatches the root initial transition into increase and checks during-state actuator outputs.',
        steps=[ScenarioStep(events=[], expected_state='ABSBrakeSupervisor.increase', expected_vars={'k1':1,'k2':0,'n':0}, name='default_initial_to_increase')],
    ),
    TestScenario(
        name='S002_increase_to_hold_at_nonpositive_error',
        description='external_input_initial_vars: slp=0.0 is an NL/paper external slip-error input satisfying slp <= 0.01.',
