        ],
    ),
    TestScenario(
        name='S003_hold_to_increase_positive_error',
        description='reachable_prefix/runtime_hotstart_surrogate: hold is reachable via default -> increase with slp<=0.01 -> hold; slp is refreshed externally to 0.02.',
        initial_state='ABSBrakeSupervisor.hold',
        initial_vars={'slp':0.02,'k1':0,'k2':0,'n':0},
        steps=[ScenarioStep(events=[], expected_state='ABSBrakeSupervisor.increase', expected_vars={'k1':1,'k2':0,'n':0}, name='guard_hold_to_increase')],
    ),
    TestScenario(
        name='S004_hold_to_decrease_negative_error',
        description='reachable_prefix/runtime_hotstart_surrogate: hold is reachable via default -> increase -> hold; slp is refreshed externally to -0.02.',
