        initial_state='ABSBrakeSupervisor.decrease',
        initial_vars={'slp':-0.01,'k1':0,'k2':1,'n':500},
        steps=[ScenarioStep(events=[], expected_state='ABSBrakeSupervisor.hold', expected_vars={'k1':0,'k2':0,'n':0}, name='guard_decrease_to_hold')],
    ),
]
