    'final_model_sha256': hashlib.sha256(final_dsl.encode()).hexdigest(),
    'initial_candidate_sha256': hashlib.sha256(initial_enter_dsl.encode()).hexdigest(),
    'final_candidate_revision_note':'Switched state output actions from enter to during to match Figure 6 Stateflow du: action semantics; behavior remains equivalent for sampled actuator outputs in this closed supervisor.',
    'commands_or_api_calls':[
        'method.stages.api.run_sd2_parse(final_dsl, StageContext)',
