        {'stage':'SC-5F','tool':'freeze_scenario_set','ok':freeze_meta.ok,'meta':jable(freeze_meta),'scenario_set':jable(scenario_set)},
        {'stage':'SD-6','tool':'run_sd6_sim','ok':sim.ok,'meta':jable(sim_meta),'feedback':jable(sim)},
    ],
    'mutation_results':mutation_results,
}
(out/'tool_stage_check_ledger.json').write_text(json.dumps(ledger, ensure_ascii=False, indent=2), encoding='utf-8')
print(json.dumps({'parse':parse.ok,'semantic':bool(sem and sem.ok),'design':bool(design and design.ok),'coverage_ok':coverage_meta.ok,'sim':sim.ok,'final_hash':hashlib.sha256(final_dsl.encode()).hexdigest(),'mutation_caught':sum(1 for m in mutation_results if m['caught'])}, ensure_ascii=False, indent=2))
PY"

